using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace RemoteDesktop.Server.Shared;

/// <summary>
/// The one event shape every server process sends to the ops console: an envelope that says who observed it, when, and
/// which connection it belongs to, plus a payload only that <see cref="Kind"/> understands.
/// </summary>
/// <remarks>
/// <para>
/// The envelope is versioned separately from the kinds: adding a kind does not change <see cref="V"/>, changing what a
/// field means does. <see cref="EventId"/> is generated by the sender so the receiver can drop a replayed batch without
/// keeping a nonce table — the console has a unique index on it instead.
/// </para>
/// <para>
/// <see cref="CorrelationId"/> is always minted on the server, never taken from a client message. The signaling
/// protocol's request id is client-chosen, so using it here would let anyone address another connection's timeline.
/// </para>
/// </remarks>
public sealed record OpsEventEnvelope
{
    /// <summary>Envelope version. Starts at 1.</summary>
    public int V { get; init; } = 1;

    /// <summary>UUIDv7 generated by the sender; the console rejects duplicates.</summary>
    public required string EventId { get; init; }

    /// <summary>Name the console knows this node by, as registered there.</summary>
    public required string Node { get; init; }

    /// <summary>One of <see cref="OpsEventKinds"/>.</summary>
    public required string Kind { get; init; }

    /// <summary>When the node observed it, by the node's clock.</summary>
    public required DateTimeOffset OccurredAt { get; init; }

    /// <summary>Server-minted id shared by every event about the same connection.</summary>
    public required string CorrelationId { get; init; }

    /// <summary>The payload as a JSON object. Kept as text so this contract never depends on a serializer's settings.</summary>
    public required string Payload { get; init; }
}

/// <summary>The event names the console understands. Unknown ones are stored and ignored, not rejected.</summary>
public static class OpsEventKinds
{
    public const string SessionRequested = "session.requested";
    public const string SessionAccepted = "session.accepted";
    public const string SessionFailed = "session.failed";
    public const string RelayPaired = "session.relay_paired";
    public const string RelayClosed = "session.relay_closed";

    /// <summary>
    /// A client's heartbeat about one of its own sessions. The only kind whose payload arrives from an end-user device
    /// rather than from a server, so <see cref="SessionTelemetry"/> validates it before it is published.
    /// </summary>
    public const string SessionTelemetry = "session.telemetry";
}

/// <summary>
/// Signs an ingest request: HMAC over <c>timestamp.body</c>, so a captured body cannot be re-dated past the receiver's
/// skew window and a captured signature cannot be moved to another body.
/// </summary>
public static class OpsEventSigner
{
    /// <summary>Header carrying the key id, so a rotated key can be told apart from the one it replaces.</summary>
    public const string KeyIdHeader = "X-Ops-Key-Id";

    /// <summary>Header carrying the Unix seconds the request was signed at.</summary>
    public const string TimestampHeader = "X-Ops-Timestamp";

    /// <summary>Header carrying the Base64 signature.</summary>
    public const string SignatureHeader = "X-Ops-Signature";

    /// <summary>Base64 HMAC-SHA256 of <paramref name="timestamp"/> + "." + <paramref name="body"/>.</summary>
    public static string Sign(ReadOnlySpan<byte> key, long timestamp, ReadOnlySpan<byte> body)
    {
        var signed = SignedBytes(timestamp, body);
        return Convert.ToBase64String(HMACSHA256.HashData(key, signed));
    }

    /// <summary>True when <paramref name="signature"/> is the signature of this timestamp and body.</summary>
    public static bool Verify(ReadOnlySpan<byte> key, long timestamp, ReadOnlySpan<byte> body, string signature)
    {
        ArgumentNullException.ThrowIfNull(signature);

        byte[] provided;
        try
        {
            provided = Convert.FromBase64String(signature);
        }
        catch (FormatException)
        {
            return false;
        }

        var signed = SignedBytes(timestamp, body);
        var expected = HMACSHA256.HashData(key, signed);
        return CryptographicOperations.FixedTimeEquals(expected, provided);
    }

    private static byte[] SignedBytes(long timestamp, ReadOnlySpan<byte> body)
    {
        var prefix = Encoding.ASCII.GetBytes(timestamp.ToString(CultureInfo.InvariantCulture) + ".");
        var signed = new byte[prefix.Length + body.Length];
        prefix.CopyTo(signed, 0);
        body.CopyTo(signed.AsSpan(prefix.Length));
        return signed;
    }
}
